module reset_sync
   (cpu_reset,
    sync_rst_reg_0,
    clk_out1,
    reset,
    mret_inhibit1,
    locked);
  output cpu_reset;
  output sync_rst_reg_0;
  input clk_out1;
  input reset;
  input mret_inhibit1;
  input locked;

  wire \<const1> ;
  wire clk_out1;
  wire cpu_reset;
  wire locked;
  wire mret_inhibit1;
  wire reset;
  wire stage1;
  wire stage1_i_1_n_0;
  wire sync_rst_i_1_n_0;
  wire sync_rst_reg_0;

  VCC VCC
       (.P(\<const1> ));
  LUT2 #(
    .INIT(4'hE)) 
    \dout[31]_i_1__0 
       (.I0(cpu_reset),
        .I1(mret_inhibit1),
        .O(sync_rst_reg_0));
  (* SOFT_HLUTNM = "soft_lutpair304" *) 
  LUT1 #(
    .INIT(2'h1)) 
    stage1_i_1
       (.I0(locked),
        .O(stage1_i_1_n_0));
  FDPE stage1_reg
       (.C(clk_out1),
        .CE(\<const1> ),
        .D(stage1_i_1_n_0),
        .PRE(reset),
        .Q(stage1));
  (* SOFT_HLUTNM = "soft_lutpair304" *) 
  LUT2 #(
    .INIT(4'hB)) 
    sync_rst_i_1
       (.I0(stage1),
        .I1(locked),
        .O(sync_rst_i_1_n_0));
  FDPE sync_rst_reg
       (.C(clk_out1),
        .CE(\<const1> ),
        .D(sync_rst_i_1_n_0),
        .PRE(reset),
        .Q(cpu_reset));
endmodule

